  ('99287fe1-ab79-5f89-8eb8-f5eada3711aa', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92A', null, 'self_development', 'E-7', null, 'Sergeant First Class — Self-Development', 'Chapter 4. MOS 92A Automated Logistical Specialist', 'For additional information on self-development, refer to Chapter 3; Army Career Tracker (ACT) at https://actnow.army.mil; TC 7-22.7; Army Training Information System (ATIS) at https://www.pdmatis.army.mil/', '037c2ced46ca2f6a6b29007cd28fee256933f9ee9d86baeb8567400a6b3a4257', 12, 12, null, 81, null, null, false, null),
