  ('26d26185-d26f-5778-9dca-43f0530be084', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92A', null, 'assignments', 'E-7', null, 'Sergeant First Class — Special assignments', 'Chapter 4. MOS 92A Automated Logistical Specialist', '1) Broadening Assignments: Detachment Sergeant, Drill Sergeant, Recruiter, Instructor, Training Developer, Senior Small Group Leader, ALC or SLC Small Group Leader, Enlisted Aide, Inspector General, Training with Industry, Equal Opportunity Advisor, SLC Instructor, SARC, Career Advancement, and White House Communications Agency (WHCA). 2) MOS Enhancing: Security Force Assistance Brigade (SFAB), Ranger Battalion or Special Operations assignments.', '147de8df230003bf73d919825dae706131432c2ff73fec35c99819002aa71eef', 12, 12, null, 83, null, null, false, null),
  ('8c31d3bd-abb3-5280-9ac4-201fb9a61403', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92A', null, 'training', 'E-8', null, 'Master Sergeant/First Sergeant — Institutional training', 'Chapter 4. MOS 92A Automated Logistical Specialist', 'SGM-A', '9dd76cebaa7df888b4fa51b65c80bd2c31219d93a2969295e38d1a4de0e16af9', 12, 12, null, 84, null, null, false, null),
