  ('93bd8a99-a44a-5665-8519-1e345e4767c1', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92L', null, 'assignments', 'E-5', null, 'Sergeant — Special assignments', 'Chapter 13. MOS 92L Petroleum Laboratory Specialist', '1) Broadening Assignments: Recruiter, Drill Sergeant, and Security Force Assistance Brigade (SFAB). 2) MOS Enhancing: Ranger Battalion, Special Mission Units, or Special Operations assignments.', 'c0dbc78a181b0daa08190fea19302a39ae2ae29187ed78f9d45bdf54c4f637d2', 24, 24, null, 169, null, null, false, null),
