  ('0fd38345-d9e8-54ac-9141-3968df61bdf4', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'assignments', 'E-1..E-4', null, 'Private E-1–Specialist/Corporal — Special assignments', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'Special assignments 1) Broadening Assignments: None 2) MOS Enhancing: Ranger Battalion or Special Operations assignments.', '93d1fc920a5680021602d57275a0850dda6b00e179cc5213a28f4433f17ab3c2', 32, 32, null, 241, null, null, false, null),
  ('037b429d-b05f-5bf7-8642-588cef72515a', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'training', 'E-5', null, 'Sergeant — Institutional training', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'ALC and Reclassification.', 'cf63d356c621c858c25193d29febe2bcb14d92ae16c3f8e8fcc8fd8e148accdf', 32, 32, null, 242, null, null, false, null),
