  ('b217d49d-091d-5fc6-93af-d071fd979dff', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'self_development', 'E-5', null, 'Sergeant — Self-development', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'For additional information on self-development, refer to chapter 3; Army Career Tracker (ACT) at https://actnow.army.mil; TC 7-22.7; Army Training Information System (ATIS) at https://www.pdmatis.army.mil/.', '7345beb1d9eab7bc9ff4d40e11cfed7f7dc794420c71074b13e9a2d06abd0275', 32, 32, null, 245, null, null, false, null),
