  ('198f6d3b-4b86-5ee7-8cb9-03cbd52ef268', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'training', 'E-6', null, 'Staff Sergeant — Institutional training', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'SLC and Reclassification.', '89465a136a1bc1d444b6ef3a5cb30f668f135a6ec2e7ca121e3e36965ce77e32', 33, 33, null, 248, null, null, false, null),
  ('70221ed1-ebee-5fd2-a94d-c2e51136641d', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'assignments', 'E-6', null, 'Staff Sergeant — Operational assignments', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'The critical developmental assignment for an MOS 92S Staff Sergeant as a Section Chief for 24 months or serving on staff for 24 months. Although the proponent recommends all MOS 92S Staff Sergeants serve a minimum of 24 months as a Section Chief prior to being assigned to other leadership duties in operational units, unit strengths, operational requirements, and unit priorities may require Commanders and Command Sergeant Majors to move Staff Sergeants prior to meeting this requirement. Assignments in Operational Army units as a Section Chief and Senior Shower/Laundry NCO.', 'd4f8289e88ed66c54a915b391a6e0199a766a8d11b0ee4f43493a533304e9243', 33, 33, null, 249, null, null, false, null),
  ('9fa3fdc2-1c27-5e48-8804-74401ea551e0', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'development', 'E-6', null, 'Staff Sergeant — TDA assignments', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'Staff Sergeants selected for TDA gain a different perspective of the unique challenges other than the operational Army. They will receive specialized training and, in some cases, access credentialing. These tours should be limited to one three-year tour, with the exception of those personnel required to complete a broadening tour in support of Army requirements. TDA assignments include Drill Sergeant, Observer Controller/Trainer, SGL, Recruiter, Instructor, and Operations Sergeant. (d) Self-development. For additional information on self-development, refer to TC 7-22.7 The NCO Guide. ACT https://actnow.army.mil.', '4a893e416c9606cd3c153d3bd990b3b5fe4fd7f25be905b3f46301d5d0de654d', 33, 33, null, 250, null, null, false, null),
  ('ba0b593d-4b9a-5619-94ed-2ebcc5fb6efc', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'training', 'E-6', null, 'Staff Sergeant — Additional Training', 'Chapter 22. MOS 92S Shower/Laundry Specialist', ', Airborne, Jumpmaster, Air Assault, Ranger, Master Resiliency Trainer, Master Fitness Trainer, Sling Load Inspector Certification Course (SLICC), Enlisted Aide Training Course, Battle Staff, Master Driver Trainer, Sexual Harassment/Assault Response and Prevention (SHARP), Support Operations Course, and Contracting Officer Representative (COR).', 'f91d47499bcc9dcf37d5e11264c1773f39602b784fdcde476e673e93ca76446f', 33, 33, null, 251, null, null, false, null),
  ('a3c505f3-52ad-552e-a082-aa6e10035715', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'assignments', 'E-6', null, 'Staff Sergeant — Special assignments', 'Chapter 22. MOS 92S Shower/Laundry Specialist', '1) Broadening Assignments: Instructor, Drill Sergeant, Recruiter, SGL, and Enlisted Aide. 2) MOS Enhancing: Ranger Battalion or Special Operations assignments.', 'c91140b891baae5f64bc3aff6cd5f6fa396b827f23073570d8a046fe5dc9fc55', 33, 33, null, 252, null, null, false, null),
  ('c9b5a2a6-ba74-5048-b765-91c6e6c0b03a', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'training', 'E-7', null, 'Sergeant First Class — Institutional training', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'MLC and Reclassification.', 'ed9311ac4790ece28b2d6195d74ee44e265d355c90ab296c515eecc651806c43', 33, 33, null, 253, null, null, false, null),
  ('18a9de20-6a77-5e2e-bcb8-bdc339eed0cb', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'assignments', 'E-7', null, 'Sergeant First Class — Operational assignments', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'The critical developmental assignment for an MOS 92S Sergeant First Class is serving on staff for 24 months. Although the proponent recommends all MOS 92S Sergeant First Class’s serve a minimum of 24 months on staff prior to being assigned to other leadership duties in operational units, unit strengths, operational requirements, and unit priorities may require Commanders and Command Sergeant Majors to move Sergeant First Class’s prior to meeting this requirement. Assignments in Operational Army units as a Platoon Sergeant, First Sergeant, and Senior Shower/Laundry NCO.', '5679eda738d0fa72c4944880bb61b600fafd5c7ba557707e38e36ea625f40bea', 33, 33, null, 254, null, null, false, null),
  ('f72d2a82-b39c-582e-9414-4705d654ab0c', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92S', null, 'development', 'E-7', null, 'Sergeant First Class — TDA assignments', 'Chapter 22. MOS 92S Shower/Laundry Specialist', 'Sergeant First Class selected for TDA gain a different perspective of the unique challenges other than the operational Army. They will receive specialized training and, in some cases, access credentialing. These tours should be limited to one three-year tour, with the exception of those personnel required to complete a broadening tour in support of Army requirements. TDA assignments include Instructor, Observer/Controller, Senior Small Group Leader, Training Developer. (d) Self-Development. For additional information on self-development, TC 7-22.7 The NCO Guide. ACT https://actnow.army.mil.', 'c8b616b10c75bda76c1854f5ae0ee009f2b5ed171b937ab7c3b3a848bbe4007d', 33, 33, null, 255, null, null, false, null),
