  ('c259fa68-75fd-5b02-b2da-2e1fdf3e9569', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92W', null, 'development', null, null, 'Goals for development', 'Chapter 25. MOS 92W Water Treatment Specialist', 'Water Treatment Specialist must focus and become proficient in the skills of their MOS and continue to broaden their knowledge that will in turn reflect on them positively later in their careers. Warrior Tasks and Battle Drills cannot be overlooked; the Quartermaster Soldier should hone the tactical skills needed to survive on the battlefield and strive for excellence during the ACFT and weapons qualification.', '6dd15dd0881062aca145db609d17d45cb0e4d2e64a3699a7a147d8920479093f', 35, 35, null, 265, null, null, false, null),
