  ('7ecea0ba-2da8-5565-9eca-fb357566f179', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92Y', null, 'self_development', 'E-7', null, 'Sergeant First Class — Self-Development', 'Chapter 28. MOS 92Y Unit Supply Specialist', 'For additional information on self-development, refer to chapter 3; Army Career Tracker (ACT) at https://actnow.army.mil; TC 7-22.7; Army Training Information System (ATIS) at https://www.pdmatis.army.mil/.', '7345beb1d9eab7bc9ff4d40e11cfed7f7dc794420c71074b13e9a2d06abd0275', 41, 41, null, 314, null, null, false, null),
  ('2568d393-ea6e-5cba-ab63-5cd3ff7a5c24', '7bb00f17-9863-5757-a81f-7038b54c0dc1', 'Army', 'enlisted', '92Y', null, 'development', 'E-7', null, 'Sergeant First Class — Additional guidance', 'Chapter 28. MOS 92Y Unit Supply Specialist', 'Additional Airborne, Jumpmaster, Air Assault, Ranger, HAZMAT Course, Sling Load Inspector Certification Course (SLICC), Battle Staff Course, Support Operations Course, Joint Logistics Course, Contracting Officer Representative (COR), Culture and Language, Enlisted Aide Training Course, Master Fitness Trainer, Sexual Harassment/Assault Response and Prevention (SHARP), Master Resilience Trainer-Assistant Primary Instructor, and Inspector General.', '206091ee480fa6119b6f9b0f0ca498a7cf2cc7280cc640f50cfca785a68b6b0d', 41, 41, null, 315, null, null, false, null),
